preConditionHook:
// Two backward-looking Extremes windows, offset against each other:
//   recent  = Highest(high, pullbackWindow)          bars 0..pullbackWindow-1
//   prior   = Highest(high[pullbackWindow], swingLookback)
//                                bars pullbackWindow..pullbackWindow+swingLookback-1
// The breakout's travel is the difference. Nothing peeks ahead: the evaluation
// bar is a bar of the pullback.
// Extremes is EL SOURCE -- seeded on the window's first bar, strict comparison
// so a tie keeps the earliest bar, and it carries the relational tolerance.
recentHigh = high[0];
recentLow = low[0];
for (int i = 1; i < (int)pullbackWindow; ++i) {
    if (el_gt(high[i], recentHigh)) recentHigh = high[i];
    if (el_lt(low[i], recentLow)) recentLow = low[i];
}
priorHigh = high[(int)pullbackWindow];
priorLow = low[(int)pullbackWindow];
for (int i = (int)pullbackWindow + 1; i < (int)pullbackWindow + (int)swingLookback; ++i) {
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
    if (el_lt(low[i], priorLow)) priorLow = low[i];
}
